kissEv('ft_kiss_itte','いってらっしゃいのキス','itte','m',0.5,function(ctx,a,b){return FC.sameHome(ctx,a,b)&& !ctx.ft.hol;});
kissEv('ft_kiss_oyasumi','おやすみ前のキス（恋人どうし）','oyasumi','n',0.6,null);
